function Dictionaries({document,baseline,onChange,onClose}:{document:Document;baseline:Document;onChange:(doc:Document)=>void;onClose:()=>void}){
 const [draft,setDraft]=useState(clone(document)),[language,setLanguage]=useState(''),[error,setError]=useState('');
 const update=(di:number,fn:(d:Document['dictionaries'][number])=>void)=>setDraft(current=>{const next=clone(current);fn(next.dictionaries[di]);next.dictionaries[di].version=(baseline.dictionaries.find(d=>d.id===next.dictionaries[di].id)?.version||0)+1;return next;});
 return <Modal title="Sözlük ve diller" onClose={onClose} wide><div className="inline-form"><label>Yeni dil kodu<input value={language} maxLength={6} placeholder="en veya pt-BR" pattern="[a-z]{2,3}(-[A-Z]{2})?" onChange={e=>setLanguage(e.target.value)}/></label><button disabled={!/^[a-z]{2,3}(-[A-Z]{2})?$/.test(language)||draft.locales.includes(language)} onClick={()=>{setDraft({...draft,locales:[...draft.locales,language]});setLanguage('');}}>Dili ekle</button></div><p>Site dilleri: {draft.locales.join(', ')}. Çeviriler editörde dil seçilerek düzenlenir.</p>
 {draft.dictionaries.map((d,di)=><details open key={d.id}><summary>{d.id} · sürüm {d.version}</summary><div className="dictionary-table"><div className="dictionary-row heading"><span>Sabit kimlik</span><span>Türkçe etiket</span><span>İngilizce etiket</span><span>Aktif</span></div>{d.entries.map((entry,ei)=><div className="dictionary-row" key={entry.id}><code>{entry.id}</code><input aria-label={entry.id+' Türkçe etiket'} maxLength={120} value={entry.labels.tr||''} onChange={e=>update(di,d=>{d.entries[ei].labels.tr=e.target.value;})}/><input aria-label={entry.id+' İngilizce etiket'} maxLength={120} value={entry.labels.en||''} onChange={e=>update(di,d=>{d.entries[ei].labels.en=e.target.value;})}/><input aria-label={entry.id+' aktif'} type="checkbox" checked={entry.active} onChange={e=>update(di,d=>{d.entries[ei].active=e.target.checked;})}/></div>)}</div><p className="hint">Pasif değerler geçmiş kayıtlarda korunur; yeni kayıtlarda seçilemez. Serbest metinler sözlükte aranmaz.</p></details>)}
 {error&&<p role="alert" className="field-error">{error}</p>}<button className="primary" onClick={()=>{const issues=validateDocument(draft,baseline);if(issues.length)setError(issues.map(e=>e.message).join(' '));else onChange(draft);}}>Değişiklikleri taslağa uygula</button></Modal>;
}
function Members({base,onClose}:{base:string;onClose:()=>void}){
 const [data,setData]=useState<any>(null),[email,setEmail]=useState(''),[selected,setSelected]=useState<string[]>(['content']),[error,setError]=useState('');
 const load=()=>api(base+'/members').then(setData);useEffect(()=>{load().catch(e=>setError(e.message));},[]);
 return <Modal title="Site erişimi" onClose={onClose}><p>İzinler yalnızca bu siteye aittir. Kullanıcı hesabı Studio’da mevcut olmalı.</p>{error&&<p role="alert" className="field-error">{error}</p>}<form onSubmit={async e=>{e.preventDefault();try{await api(base+'/members','PUT',{email,permissions:selected});await load();setEmail('');}catch(e:any){setError(e.message);}}}><label>E-posta<input type="email" required maxLength={254} value={email} onChange={e=>setEmail(e.target.value)}/></label><div className="permission-list">{data?.available.map((p:string)=><label className="check" key={p}><input type="checkbox" checked={selected.includes(p)} onChange={e=>setSelected(e.target.checked?[...selected,p]:selected.filter(x=>x!==p))}/>{({content:'İçerik',design:'Tasarım',import:'Import',operations:'Rezervasyon ve takvim',integrations:'Entegrasyon',publish:'Yayın',members:'Üye yönetimi'} as any)[p]}</label>)}</div><button className="primary">İzinleri kaydet</button></form>{data?.members.map((m:any)=><div className="member-row" key={m.user_id}><div><strong>{m.email}</strong><p>{m.permissions.join(', ')||'Salt okunur'}</p></div><button onClick={async()=>{try{await api(base+'/members','DELETE',{userId:m.user_id});await load();}catch(e:any){setError(e.message);}}}>Erişimi kaldır</button></div>)}</Modal>;
}
function Operations({base,site,onClose}:{base:string;site:any;onClose:()=>void}){
 const [enabled,setEnabled]=useState<boolean|null>(null),[view,setView]=useState(site.permissions.includes('operations')?'bookings':'connect'),[error,setError]=useState(''),[message,setMessage]=useState(''),container=useRef<HTMLDivElement>(null);
 const views=[...(site.permissions.includes('operations')?[['bookings','Rezervasyonlar'],['calendar','Takvim'],['bookingSettings','Rezervasyon ayarları']]:[]),...(site.permissions.includes('integrations')?[['connect','Entegrasyonlar']]:[])];
 useEffect(()=>{api(base+'/modules').then(result=>setEnabled(result.enabled)).catch(e=>setError(e.message));},[]);
 useEffect(()=>{if(!enabled||!container.current)return;const el=container.current;void mountFeatures({container:el,view,site:{id:site.id,role:'admin'},baseUrl:base+'/modules',api:(url:string,options?:any)=>api(url,options?.method||'GET',options?.body?JSON.parse(options.body):undefined),toast:(text:string,err?:boolean)=>err?setError(text):setMessage(text),navigate:(next:string)=>setView(next)});return()=>{(el as any)._featureContext=null;(window as any).studioFeatureDirty=()=>false;};},[enabled,view]);
 const leave=(fn:()=>void)=>{if((window as any).studioFeatureDirty?.()&&!window.confirm('Bu ekranda kaydedilmemiş alanlar var. Yine de ayrılmak istiyor musunuz?'))return;fn();};
 return <Modal title="İş modülleri" onClose={()=>leave(onClose)} wide>{error&&<p role="alert" className="error-banner">{error}</p>}{message&&<p role="status" className="notice">{message}</p>}{enabled===false?<div className="empty-state"><h3>Rezervasyon, takvim ve entegrasyonlar</h3><p>Bu site için ayrı operasyon kayıtları oluşturulur. Çevrimiçi rezervasyon ve ödeme sağlayıcıları başlangıçta kapalıdır.</p><button className="primary" disabled={!site.permissions.includes('operations')||!site.permissions.includes('integrations')} onClick={async()=>{try{await api(base+'/modules/enable','POST',{});setEnabled(true);}catch(e:any){setError(e.message);}}}>İş modüllerini kur</button></div>:enabled?<><nav className="module-tabs" aria-label="İş modülleri">{views.map(([id,label])=><button className={view===id?'primary':''} key={id} onClick={()=>leave(()=>setView(id))}>{label}</button>)}</nav><div className="module-content" ref={container}/></>:<p>Modüller yükleniyor…</p>}</Modal>;
}
createRoot(document.getElementById('root')!).render(<App/>);
